import { Message } from '../utils/types'
import { AssistantMessage } from './AssistantMessage'
import { UserMessage } from './UserMessage'
import { defineStyles } from '@/utils/defineStyles'
import { ChatFooterContainer } from './ChatFooterContainer'
import { getVisibleBlocks } from '../utils/get-visible-blocks'
import { CollapseButton } from './CollapseButton'
import { useCallback, useEffect, useMemo } from 'react'
import { PulsingDot } from './PulsingDot'
import { LayoutChangeEvent, View } from 'react-native'
import { useChatStore } from '../store/chatStore'
import { MESSAGE_BOTTOM_CONTAINER_GAP, MESSAGE_GAP } from '@/constants'
import { MotiView } from 'moti'

export const ChatBlock = ({
	message,
	chatHeight,
	isLastUserMessage,
	bottomContainerHeight,
	isLauncher
}: {
	message: Message
	chatHeight: number
	isLastUserMessage: boolean
	bottomContainerHeight: number
	isLauncher: boolean
}) => {
	const isUser = message.actor === 'user'
	const isAssistant = message.actor === 'assistant'
	const lastUserMessageHeight = useChatStore(
		(state) => state.value.lastUserMessageHeight
	)
	const setLastUserMessageHeight = useChatStore(
		(state) => state.setLastUserMessageHeight
	)
	const currentMessageId = useChatStore((state) => state.value.currentMessageId)
	const setCurrentMessageId = useChatStore((state) => state.setCurrentMessageId)
	const chatState = useChatStore((state) => state.value.chatState)
	const setChatState = useChatStore((state) => state.setChatState)

	useEffect(() => {
		if (
			chatState === 'PENDING' &&
			message.isGenerating &&
			message.actor === 'assistant' &&
			message.revision &&
			!message.id.startsWith('optimistic-')
		) {
			setCurrentMessageId(message.id)
			setChatState('GENERATING')
		}
	}, [message.blocks])

	const { visible, collapsed } = useMemo(() => {
		return getVisibleBlocks({
			isGenerating: message.isGenerating,
			blocks: message.blocks
		})
	}, [message.isGenerating, message.blocks])

	const handleUserMessageLayout = useCallback(
		(event: LayoutChangeEvent) => {
			if (!isLastUserMessage) return
			const { height } = event.nativeEvent.layout
			setLastUserMessageHeight(height)
		},
		[isLastUserMessage, setLastUserMessageHeight]
	)

	const renderUserMessage = useCallback(() => {
		return (
			<View onLayout={handleUserMessageLayout}>
				{message.blocks.map((block, index) => {
					return <UserMessage key={index} block={block} />
				})}
			</View>
		)
	}, [handleUserMessageLayout, message.blocks])

	const renderAssistantMessage = useCallback(() => {
		if (
			message.isGenerating &&
			message.blocks.every((block) => {
				if (block.type === 'text') {
					return !block.code?.trim()
				}
				if (block.type === 'animated-text') {
					return !block.text?.trim()
				}
				return false
			})
		) {
			return <PulsingDot />
		}
		return (
			<View style={styles.assistantMessageContainer}>
				{message.blocks.length > 1 && (
					<CollapseButton messageId={message.id} collapsedData={collapsed} />
				)}
				{visible.map((block, index) => {
					const isLastVisibleBlock = index === visible.length - 1
					return (
						<AssistantMessage
							key={index}
							messageId={message.id}
							block={block}
							isGenerating={message.isGenerating}
							isLastBlock={isLastVisibleBlock}
							isOnlyBlock={message.blocks.length === 1}
							isLauncher={isLauncher}
						/>
					)
				})}
			</View>
		)
	}, [message.isGenerating, message.blocks, collapsed, visible])

	const fillerHeight = useMemo(
		() =>
			chatHeight -
			lastUserMessageHeight -
			MESSAGE_BOTTOM_CONTAINER_GAP * 4 -
			bottomContainerHeight -
			20,
		[chatHeight, lastUserMessageHeight, bottomContainerHeight]
	)

	return (
		<View
			style={[
				isAssistant &&
					message.isLatest && {
						minHeight: fillerHeight
					}
			]}
		>
			<MotiView
				from={
					currentMessageId !== message.id
						? { translateY: -fillerHeight }
						: undefined
				}
				animate={
					currentMessageId !== message.id ? { translateY: 0 } : undefined
				}
				transition={{ type: 'timing', duration: 300 }}
				style={styles.responseContainer}
			>
				<View style={styles.messagesContainer}>
					{isUser ? renderUserMessage() : renderAssistantMessage()}
				</View>
				<View style={styles.footerContainer}>
					{(isUser ||
						(!message.isGenerating && currentMessageId !== message.id) ||
						chatState === 'READY') && <ChatFooterContainer message={message} />}
				</View>
			</MotiView>
		</View>
	)
}

const styles = defineStyles({
	responseContainer: {
		gap: MESSAGE_GAP
	},
	messagesContainer: {
		gap: MESSAGE_GAP
	},
	footerContainer: {
		height: 26
	},
	assistantMessageContainer: {
		gap: MESSAGE_GAP
	}
})
